var TINH_MAP   = {"Binhtt6":["HUE","TQG"],"Chungdd2":["DNG","NAN","QNI"],"Congnd15":["HTH","KHA","TNH"],"Dangph11":["AGG","CMU","DLK","LDG"],"Datnt547":["DNI","HCM","NBH","QTI"],"Hieutv4":["BNH","HPG","QNH","TNN"],"Thaoltt16":["HYN","VLG"],"Truongdv17":["HNI","PTO"]};
